import random
import struct
from typing import List

# Generator for an arbitrary binary buffer aimed at exercising c_fifo::write
# The fuzzer stub uses FUZZ_PARAM_STR() to obtain a std::string payload, then writes up to 128 bytes.
# Our goal: return bytes that are interesting and valid (non-empty), cover various lengths and byte patterns,
# and remain <= 4096 bytes. We produce between 1 and 256 bytes to keep within the stub cap and vary scenarios.

_PRINTABLE = [
    0x00, 0x01, 0x02, 0x03, 0x04, 0x07, 0x08, 0x09, 0x0A, 0x0D, 0x1B,
] + list(range(0x20, 0x7F))


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.randrange(0, 256) for _ in range(n))


def _pattern_repeated(rng: random.Random, length: int) -> bytes:
    # Choose a small motif 1..16 bytes and repeat to length
    motif_len = rng.randint(1, 16)
    motif_choice = rng.choice([
        bytes([0x00]) * motif_len,
        bytes([0xFF]) * motif_len,
        bytes([0x55]) * motif_len,
        bytes([0xAA]) * motif_len,
        bytes(rng.randrange(0, 256) for _ in range(motif_len)),
    ])
    return (motif_choice * (length // motif_len + 1))[:length]


def _structured_header_payload(rng: random.Random, length: int) -> bytes:
    # Create a simple header + payload structure to emulate framed writes
    # [magic(2)][version(1)][len(1)][flags(1)][checksum(1)][payload]
    # Ensure total equals requested length; payload may be truncated/padded
    header_len = 6
    if length <= header_len:
        return _rand_bytes(rng, length)
    magic = rng.choice([b"GF", b"IO", b"WB", struct.pack('>H', rng.randrange(0, 65536))])
    version = rng.randrange(0, 8)
    flags = rng.randrange(0, 256)
    payload_len = length - header_len
    payload = _rand_bytes(rng, payload_len)
    # Simple checksum: sum of payload modulo 256
    checksum = sum(payload) & 0xFF
    hdr = magic[:2] + bytes([version, payload_len & 0xFF, flags, checksum])
    return hdr + payload


def _text_like(rng: random.Random, length: int) -> bytes:
    # Mostly printable ASCII with occasional control characters and multibyte-like sequences
    data = bytearray()
    while len(data) < length:
        choice = rng.random()
        if choice < 0.75:
            data.append(rng.choice(_PRINTABLE))
        elif choice < 0.90:
            # UTF-8-ish multibyte prefix + continuation
            first = rng.choice([0xC2, 0xC3, 0xD0, 0xE2])
            cont = 0x80 | rng.randrange(0, 64)
            data.extend([first, cont])
        else:
            data.append(rng.randrange(0, 256))
    return bytes(data[:length])


def _edge_lengths(rng: random.Random) -> int:
    # Favor interesting sizes for ring buffers and IO paths, limited to 1..256
    choices: List[int] = [1, 2, 3, 15, 16, 31, 32, 63, 64, 65, 95, 96, 127, 128, 129, 255, 256]
    if rng.random() < 0.7:
        return rng.choice(choices)
    return rng.randint(1, 256)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    length = _edge_lengths(rng)

    # Choose a content generator strategy
    strategy = rng.choices(
        population=[
            'random',          # pure random bytes
            'pattern',         # repeated motifs like 0x00/0xFF/0x55/0xAA or random motif
            'structured',      # simple header + payload with checksum
            'text',            # mostly printable ascii
            'mixed'            # chunks of different types
        ],
        weights=[0.25, 0.20, 0.20, 0.20, 0.15],
        k=1
    )[0]

    if strategy == 'random':
        buf = _rand_bytes(rng, length)
    elif strategy == 'pattern':
        buf = _pattern_repeated(rng, length)
    elif strategy == 'structured':
        buf = _structured_header_payload(rng, length)
    elif strategy == 'text':
        buf = _text_like(rng, length)
    else:
        # mixed: concatenate small segments of varying patterns
        buf_parts: List[bytes] = []
        remaining = length
        while remaining > 0:
            seg_len = min(remaining, max(1, int(rng.expovariate(1/16))) )
            seg_len = max(1, min(seg_len, remaining))
            pick = rng.choice(['r', 'p', 's', 't'])
            if pick == 'r':
                seg = _rand_bytes(rng, seg_len)
            elif pick == 'p':
                seg = _pattern_repeated(rng, seg_len)
            elif pick == 's':
                seg = _structured_header_payload(rng, seg_len)
            else:
                seg = _text_like(rng, seg_len)
            buf_parts.append(seg)
            remaining -= len(seg)
        buf = b''.join(buf_parts)[:length]

    # Ensure non-empty and max 4096 per requirements (length already within 256)
    if not buf:
        buf = b"\x00"
    return buf
